using System;
using System.IO;
using System.Collections.Generic;
using System.Collections;
using UnityEngine;
using Unity.Profiling;
namespace SporeGobbo.Geometry.Preview
{
 [DefaultExecutionOrder(1450)] public sealed class Stage51Benchmark:MonoBehaviour
 {
  [Serializable] public class Sample{public string phase;public double interval,host,cover,discovery,dig,build,unload;public long allocated;public int residents,pooled,presentations,edits;public bool ready,loading;public long managed,unityMemory;public int buffers,materials;}
  [Serializable] public class Result{public string machine;public List<Sample> samples=new List<Sample>();public List<string> checks=new List<string>();public List<double> transfers=new List<double>();public List<long> allocationProbe=new List<long>();public int completed,cancelled,owned;public long stateBytes;public string error="";}
  DualTile remoteEdit;Stage51Preview env;Stage47Preview live;Stage49Preview cam;Result result=new Result();string output;ProfilerRecorder alloc;double previous;string phase="warmup";
  IEnumerator Start()
  {
   var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-stage51Output");if(i<0)yield break;output=args[i+1];Directory.CreateDirectory(output);Directory.CreateDirectory(Path.Combine(output,"captures"));env=GetComponent<Stage51Preview>();env.Initialize();live=env.Live;cam=env.Lab.CameraStudy;live.automation=env.automation=env.Lab.automation=true;live.showUI=env.showPanel=env.Lab.showPanel=false;env.Lab.paused=true;env.Lab.encounterCount=0;cam.normalOverlay=false;cam.captureLabel=false;Application.runInBackground=true;QualitySettings.vSyncCount=0;Application.targetFrameRate=-1;result.machine=SystemInfo.processorType+" / "+SystemInfo.graphicsDeviceName;alloc=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame");
   yield return WaitReady();for(int probe=0;probe<4;probe++){var buffer=new byte[1024*1024];buffer[0]=1;GC.KeepAlive(buffer);yield return null;result.allocationProbe.Add(alloc.Valid?alloc.LastValue:-1);}yield return Frames("ordinary-exploration",360,true);
   yield return Capture("01-Strong-fossil");for(int profile=1;profile<4;profile++){cam.Apply(profile);yield return Capture("01p"+profile+"-fossil");}cam.Apply(0);env.showProtected=true;env.showChunks=true;yield return Capture("02-protected-boundaries");env.showProtected=env.showChunks=false;
   env.Go(r=>r.P(29,-18));yield return WaitReady();yield return Capture("03-concealed-before-breakthrough");
   var rgn=env.State.Region;int protectedBefore=0;for(int y=rgn.Y-12;y<=rgn.Y+10;y++)for(int x=rgn.X-23;x<=rgn.X+13;x++)if(rgn.Protected(x,y)){if(env.State.World.Excavate(x,y))throw new Exception("Protected excavation succeeded");protectedBefore++;}result.checks.Add("Rejected "+protectedBefore+" protected excavation attempts");
   live.brush=DigBrush.Single;live.DigAt(new Vector2(rgn.X+32.5f,rgn.Y-17.5f));env.NotifyExcavation();Check(env.State.Discovered,"Actual one-cell breakthrough discovers preexisting chamber");yield return Capture("04-chamber-gradual-start");yield return Frames("revealed-chamber",120,false);while(env.State.Reveal<1)yield return null;yield return Capture("05-chamber-revealed");
   env.Go(r=>r.CoverEntry);yield return WaitReady();yield return Capture("06-covered-sealed-entrance");live.DigAt(new Vector2(rgn.X-31.5f,rgn.Y+23.5f));env.NotifyExcavation();Check(env.State.CoverOpened,"Excavating cover entrance opens floor, leaves overhead independent");env.Go(r=>r.P(-18,23));yield return WaitReady();env.cutaway=false;yield return Capture("07-under-cover-opaque");env.cutaway=true;env.gradualCutaway=false;yield return Frames("cover-immediate-cutaway",180,false);yield return Capture("08-under-cover-cutaway");env.Lab.encounterCount=1;env.Lab.footprint=7;env.Lab.Restart();env.cutaway=false;yield return Capture("08-large-actor-opaque-cover");env.cutaway=true;yield return Capture("08-large-actor-cutaway");env.Lab.encounterCount=0;env.gradualCutaway=true;env.Go(r=>r.CoverEntry);yield return new WaitForSeconds(.45f);env.Go(r=>r.P(-18,23));yield return Capture("08b-gradual-cutaway-start");yield return Frames("cover-gradual-cutaway",180,false);yield return new WaitForSeconds(.45f);yield return Capture("08c-gradual-cutaway-complete");
   cam.Apply(2);yield return Capture("09-profileC-cover");cam.Apply(0);cam.freezeFocus=true;live.SetPreviewFocus(live.Position-new Vector2(0,17));yield return Capture("09b-foreground-cover-cutaway");cam.freezeFocus=false;live.SetPreviewFocus(live.Position);
   env.Go(r=>r.Entry);yield return WaitReady();env.Lab.encounterCount=4;env.Lab.footprint=7;env.Lab.paused=false;env.Lab.Restart();env.Lab.showPaths=true;yield return Frames("large-actors-landmark",240,true);yield return Capture("10-seven-cell-actors");env.Lab.encounterCount=0;env.Lab.showPaths=false;env.Lab.paused=true;
   // Local edits beside protected structure, through normal local rebuild path.
   phase="dig-near-landmark";int realDigs=0;for(int y=rgn.Y-8;y<=rgn.Y+8&&realDigs<16;y++)for(int x=rgn.X+2;x<=rgn.X+11&&realDigs<16;x++)if(live.World.IsSolid(x,y)&&!live.World.Locked(x,y)){int changed=live.DigAt(new Vector2(x+.5f,y+.5f));Check(changed==1,"Real dirt excavation near protected fossil "+realDigs);realDigs++;yield return Frames(phase,4,false);}Check(realDigs==16,"Measured 16 actual adjacent dirt excavations");yield return Capture("10b-fossil-after-adjacent-excavation");Check(env.State.World.IsSolid(rgn.X-6,rgn.Y-2),"Protected spine remains solid after adjacent excavation");
   env.Go(r=>r.P(-35,3));yield return WaitReady();Check(env.BeginTravel(),"Begin interrupted preparation");yield return null;env.CancelTravel();Check(env.Transfer.Transfers==0&&Vector2.Distance(live.Position,new Vector2(rgn.X-34.5f,rgn.Y+3.5f))<.01,"Cancellation leaves source position unchanged");yield return WaitReady();
   for(int n=0;n<8;n++)
   {
    Check(env.BeginTravel(),"Begin travel "+n);phase="traversal-preparation";previous=Time.realtimeSinceStartupAsDouble;int timeout=0;while(env.Loading&&timeout++<2000){yield return null;Record();}Check(!env.Loading&&env.Transfer.Transfers==n+1&&live.Ready,"Exactly-once ready transfer "+n);result.transfers.Add(env.PreparationMs);yield return Frames("arrival-exploration",35,false);
    if(n==0){yield return Capture("11-remote-arrival");bool dug=false;for(int y=(int)rgn.Remote.Y;y<(int)rgn.Remote.Y+10&&!dug;y++)for(int x=(int)rgn.Remote.X+20;x<(int)rgn.Remote.X+32&&!dug;x++)if(live.World.IsSolid(x,y)&&!live.World.Locked(x,y)){remoteEdit=new DualTile(x,y);dug=live.Stream.Dig(new List<DualTile>{remoteEdit})==1;}Check(dug,"Excavated actual destination dirt through incremental stream");}
    if(n>0)Check(!live.World.IsSolid(remoteEdit.X,remoteEdit.Y),"Destination excavation survives revisit "+n);
   }
   Check(env.State.Discovered&&env.State.CoverOpened,"Discovery and cover state survive repeated eviction");Check(!env.State.World.IsSolid(rgn.X+32,rgn.Y-18),"Source excavation survives remote travel");
   using(var s=new MemoryStream()){env.State.Save(s);result.stateBytes=s.Length;s.Position=0;var restored=EnvironmentState.Load(s);Check(restored.Discovered&&restored.CoverOpened&&restored.World.EditCount==env.State.World.EditCount,"Isolated state round trip preserves fixture and deltas");}
   env.SaveState();env.ResetDemo();env.LoadState();Check(env.State.Discovered&&env.State.CoverOpened&&!env.State.World.IsSolid(remoteEdit.X,remoteEdit.Y),"Actual isolated file save/load reconstructs host state");yield return WaitReady();env.Go(r=>r.P(29,-18));yield return Capture("11b-loaded-discovered-room");
   for(int n=0;n<5;n++){env.ResetDemo();yield return WaitReady();Check(env.OwnedMeshes==7&&env.Lab.OwnedMeshes==46&&live.Stream.Resident.Count<=384,"Reset bounded resources "+n);}
   env.State.Gradual=false;env.Go(r=>r.P(29,-18));yield return WaitReady();live.brush=DigBrush.Single;live.DigAt(new Vector2(env.State.Region.X+32.5f,env.State.Region.Y-17.5f));env.NotifyExcavation();Check(env.State.Reveal==1&&env.State.Discovered,"Immediate reveal opens presentation without transition delay");yield return Capture("12-immediate-chamber-reveal");result.completed=8;result.cancelled=env.CancelledTransfers;result.owned=env.OwnedMeshes;Finish();
  }
  void Check(bool value,string name){result.checks.Add((value?"PASS ":"FAIL ")+name);if(!value){result.error=name;Finish();throw new Exception(name);}}
  IEnumerator WaitReady(){int n=0;do{yield return null;if(n++>2500){result.error="Terrain readiness timed out";Finish();throw new Exception(result.error);}}while(!live.Ready||env.Loading);for(int i=0;i<5;i++)yield return null;}
  IEnumerator Frames(string name,int count,bool walk){phase=name;previous=Time.realtimeSinceStartupAsDouble;for(int n=0;n<count;n++){if(!env.Lab.paused)env.Lab.Advance(1.0/60);if(walk)live.Step(new Vector2(Mathf.Sin(n*.03f),Mathf.Cos(n*.025f)),Vector2.right,false,1f/60);yield return null;Record();}}
  void Record(){double now=Time.realtimeSinceStartupAsDouble;result.samples.Add(new Sample{phase=phase,interval=(now-previous)*1000,host=live.DisplayMs,cover=env.CoverMs,discovery=env.DiscoveryMs,dig=live.Stream.DigMs,build=live.Stream.BuildMs,unload=live.Stream.UnloadMs,allocated=alloc.Valid?alloc.LastValue:-1,residents=live.Stream.Resident.Count,pooled=live.Stream.PooledData,presentations=live.PooledPresentations,edits=live.World.EditCount,ready=live.Ready,loading=env.Loading,managed=GC.GetTotalMemory(false),unityMemory=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),buffers=live.Gpu.BufferCount,materials=live.Gpu.ResourceCount});previous=now;}
  IEnumerator Capture(string name){yield return WaitReady();cam.Capture(Path.Combine(output,"captures"),name);while(cam.CapturePending)yield return null;File.WriteAllText(Path.Combine(output,"captures",name+".environment.json"),JsonUtility.ToJson(new CaptureState{discovered=env.State.Discovered,reveal=env.State.Reveal,coverOpened=env.State.CoverOpened,cutaway=env.cutaway,playerX=live.Position.x,playerY=live.Position.y,profile=cam.profile,residents=live.Stream.Resident.Count,roomX=ScreenPoint(env.State.Region.Chamber).x,roomY=ScreenPoint(env.State.Region.Chamber).y,dirtX=ScreenPoint(env.State.Region.P(41,-33)).x,dirtY=ScreenPoint(env.State.Region.P(41,-33)).y},true));}
  Vector2 ScreenPoint(Point2 p){var q=live.Snapshot.Project(p);var v=live.previewCamera.WorldToScreenPoint(new Vector3((float)q.X,-(float)q.Y));return new Vector2(v.x,Screen.height-v.y);}
  [Serializable] class CaptureState{public bool discovered,coverOpened,cutaway;public double reveal;public float playerX,playerY,roomX,roomY,dirtX,dirtY;public int profile,residents;}
  void Finish(){File.WriteAllText(Path.Combine(output,"result.json"),JsonUtility.ToJson(result,true));alloc.Dispose();Application.Quit(string.IsNullOrEmpty(result.error)?0:1);}
 }
